        ctx.fillRect(mx - 4, my - 24, 8, 7);
        ctx.fillStyle = '#451a03';
        ctx.fillRect(mx - 4, my - 26, 8, 3);
        ctx.fillRect(mx - 3, my - 19, 6, 2);

        // BALCÓN SUPERIOR DE BARANDA CELESTE SÓLIDA (caminito 1.jfif)
        ctx.fillStyle = '#06b6d4';
        ctx.fillRect(fx - 2, 248, fw + 4, 34);
