        ctx.fillStyle = '#fde047';
        ctx.fillRect(cartX - 18, groundLineY - 64, 36, 6);
        ctx.strokeStyle = '#dc2626';
        ctx.lineWidth = 2.2;
        ctx.strokeRect(cartX - 21, groundLineY - 92, 42, 34);
        // Gabinete rojo inferior + manija + rueda radial clásica
