            ctx.fillRect(cx + px + 5.5, atrioY - 122, 2.5, 118);
            ctx.fillStyle = '#f5d29c';
            ctx.fillRect(cx + px - 1.5, atrioY - 126, 11, 5);
            ctx.fillRect(cx + px - 1.5, atrioY - 6, 11, 6);
